// Парсинг ответа от Perplexity AI
const response = $input.item.json;
const templateData = $('⚠️ НАСТРОЙТЕ ДАННЫЕ КОМПАНИИ').item.json;

let emailData = {};

try {
  let aiContent = response.choices?.[0]?.message?.content || '{}';
  aiContent = aiContent.replace(/```json\n?/g, '').replace(/```/g, '').trim();
  emailData = JSON.parse(aiContent);
} catch (e) {
  // Fallback если AI не вернул валидный JSON
  emailData = {
    subject: `Коммерческое предложение от ${templateData.sender_company}`,
    body: `<p>Уважаемые коллеги из ${templateData.recipient_company}!</p><p>Предлагаем рассмотреть сотрудничество.</p><p>С уважением,<br>${templateData.sender_contact}</p>`
  };
}

return {
  json: {
    site_id: templateData.site_id,
    company_name: templateData.recipient_company,
    email: templateData.recipient_email,
    subject: emailData.subject,
    body: emailData.body,
    generated_at: new Date().toISOString()
  }
};
